<?php                                                                                                                                                                                                                                                               
    App::uses('Xml', 'Utility');                                                                                                                                                                                                                                        
                                                                                                                                                                                                                                                                        
    /**                                                                                                                                                                                                                                                                 
     * CIOMS E2B (R2 and R3) XML Parser                                                                                                                                                                                                                                 
     * Ingests legacy R2 and modern HL7 v3 ISO 27953-2 (R3) safety reports.                                                                                                                                                                                             
     */                                                                                                                                                                                                                                                                 
    class CiomsR3Parser                                                                                                                                                                                                                                                 
    {                                                                                                                                                                                                                                                                   
        /**                                                                                                                                                                                                                                                             
         * Detect format, parse, and return unified data array.                                                                                                                                                                                                         
         *                                                                                                                                                                                                                                                              
         * @param string $xmlContent                                                                                                                                                                                                                                    
         * @return array ['version' => 'R2'|'R3', 'summary' => array, 'raw' => array]                                                                                                                                                                                   
         */                                                                                                                                                                                                                                                             
        public static function parse($xmlContent)                                                                                                                                                                                                                       
        {                                                                                                                                                                                                                                                               
            $xmlContent = trim((string)$xmlContent);                                                                                                                                                                                                                    
            if ($xmlContent === '') {                                                                                                                                                                                                                                   
                return array('version' => 'R2', 'summary' => array(), 'raw' => array());                                                                                                                                                                                
            }                                                                                                                                                                                                                                                           
                                                                                                                                                                                                                                                                        
            $version = self::detectVersion($xmlContent);                                                                                                                                                                                                                
                                                                                                                                                                                                                                                                        
            if ($version === 'R3') {                                                                                                                                                                                                                                    
                return array(                                                                                                                                                                                                                                           
                    'version' => 'R3',                                                                                                                                                                                                                                  
                    'summary' => self::parseR3($xmlContent),                                                                                                                                                                                                            
                    'raw' => array()                                                                                                                                                                                                                                    
                );                                                                                                                                                                                                                                                      
            }                                                                                                                                                                                                                                                           
                                                                                                                                                                                                                                         
            $raw = array();                                                                                                                                                                                                                                             
            try {                                                                                                                                                                                                                                                       
                $raw = Xml::toArray(Xml::build($xmlContent));                                                                                                                                                                                                           
            } catch (Exception $e) {                                                                                                                                                                                                           
            }                                                                                                                                                                                                                                                           
                                                                                                                                                                                                                                                                        
            return array(                                                                                                                                                                                                                                               
                'version' => 'R2',                                                                                                                                                                                                                                      
                'summary' => array(),                                                                                                                                                                                                                                   
                'raw' => $raw                                                                                                                                                                                                                                           
            );                                                                                                                                                                                                                                                          
        }                                                                                                                                                                                                                                                               
                                                                                                                                                                                                                                                                  
        public static function detectVersion($xmlContent)                                                                                                                                                                                                               
        {                                                                                                                                                                                                                                                               
            if (                                                                                                                                                                                                                                                        
                stripos($xmlContent, 'MCCI_IN200100UV01') !== false ||                                                                                                                                                                                                  
                stripos($xmlContent, 'PORR_IN049016') !== false ||                                                                                                                                                                                                      
                stripos($xmlContent, 'urn:hl7-org:v3') !== false                                                                                                                                                                                                        
            ) {                                                                                                                                                                                                                                                         
                return 'R3';                                                                                                                                                                                                                                            
            }                                                                                                                                                                                                                                                           
                                                                                                                                                                                                                                                                        
            return 'R2';                                                                                                                                                                                                                                                
        }                                                                                                                                                                                                                                                               
                                                                                                                                                                                                                                                                        
                                                                                                                                                                                                                                                                   
        public static function parseR3($xmlContent)                                                                                                                                                                                                                     
        {                                                                                                                                                                                                     
            $cleanXml = preg_replace('/xmlns(:\w+)?="[^"]*"/', '', $xmlContent);                                                                                                                                                                                        
            $cleanXml = preg_replace('/<(\/)?(\w+):/', '<$1', $cleanXml);                                                                                                                                                                                               
                                                                                                                                                                                                                                                                        
            libxml_use_internal_errors(true);                                                                                                                                                                                                                           
            $xml = simplexml_load_string($cleanXml);                                                                                                                                                                                                                    
            if ($xml === false) {                                                                                                                                                                                                                                       
                return array();                                                                                                                                                                                                                                         
            }                                                                                                                                                                                                                                                           
                                                                                                                                                                                                                                                                        
            $summary = array(                                                                                                                                                                                                                                           
                'safetyreportid' => '',                                                                                                                                                                                                                                 
                'occurcountry' => '',                                                                                                                                                                                                                                   
                'patientinitial' => '',                                                                                                                                                                                                                                 
                'patientsex' => '',                                                                                                                                                                                                                                     
                'patientbirthdate' => '',                                                                                                                                                                                                                               
                'patientonsetage' => '',                                                                                                                                                                                                                                
                'reactionstartdate' => '',                                                                                                                                                                                                                              
                'reaction_description' => '',                                                                                                                                                                                                                           
                'reactionoutcome' => '',                                                                                                                                                                                                                                
                'seriousness' => array(                                                                                                                                                                                                                                 
                    'death' => 'No',                                                                                                                                                                                                                                    
                    'life_threatening' => 'No',                                                                                                                                                                                                                         
                    'hospitalization' => 'No',                                                                                                                                                                                                                          
                    'disability' => 'No',                                                                                                                                                                                                                               
                    'other' => 'No',                                                                                                                                                                                                                                    
                ),                                                                                                                                                                                                                                                      
                'drugs' => array(),                                                                                                                                                                                                                                     
                'narrative' => '',                                                                                                                                                                                                                                      
            );                                                                                                                                                                                                                                                          
                                                                                                                                                                                                                                                        
            $reportIds = $xml->xpath('//investigationEvent/id/@extension');                                                                                                                                                                                             
            if (!empty($reportIds)) {                                                                                                                                                                                                                                   
                $summary['safetyreportid'] = (string)$reportIds[0];                                                                                                                                                                                                     
            }                                                                                                                                                                                                                                                           
                                                                                                                                                                                                                                                            
            $countries = $xml->xpath('//location//locatedPlace/code/@code');                                                                                                                                                                                            
            if (!empty($countries)) {                                                                                                                                                                                                                                   
                $summary['occurcountry'] = (string)$countries[0];                                                                                                                                                                                                       
            }                                                                                                                                                                                                                                                           
                                                                                                                                                                                                                                           
            $names = $xml->xpath('//subject1/patient/name');                                                                                                                                                                                                            
            if (!empty($names)) {                                                                                                                                                                                                                                       
                $summary['patientinitial'] = (string)$names[0];                                                                                                                                                                                                         
            }                                                                                                                                                                                                                                                           
                                                                                                                                                                                                                                                                        
            $genders = $xml->xpath('//subject1/patient/patientPerson/administrativeGenderCode/@code');                                                                                                                                                                  
            if (!empty($genders)) {                                                                                                                                                                                                                                     
                $genderCode = (string)$genders[0];                                                                                                                                                                                                                      
                $genderMap = array('1' => 'Male', '2' => 'Female', '3' => 'Other');                                                                                                                                                                                     
                $summary['patientsex'] = isset($genderMap[$genderCode]) ? $genderMap[$genderCode] : $genderCode;                                                                                                                                                        
            }                                                                                                                                                                                                                                                           
                                                                                                                                                                                                                                                                        
            $birthDates = $xml->xpath('//subject1/patient/patientPerson/birthTime/@value');                                                                                                                                                                             
            if (!empty($birthDates)) {                                                                                                                                                                                                                                  
                $summary['patientbirthdate'] = (string)$birthDates[0];                                                                                                                                                                                                  
            }                                                                                                                                                                                                                                                           
                                                                                                                                                                                                                                                                        
            $ages = $xml->xpath('//subjectOf2/observation[code/@code="26" or code/@code="age"]/value/@value');                                                                                                                                                          
            if (!empty($ages)) {                                                                                                                                                                                                                                        
                $summary['patientonsetage'] = (string)$ages[0];                                                                                                                                                                                                         
            }                                                                                                                                                                                                                                                           
                                                                                                                                                                                                                                    
            $reactions = $xml->xpath('//subjectOf2/observation[code/@code="29" or code/@code="reaction"]');                                                                                                                                                             
            if (!empty($reactions)) {                                                                                                                                                                                                                                   
                foreach ($reactions as $rx) {                                                                                                                                                                                                                           
                    if (empty($summary['reaction_description'])) {                                                                                                                                                                                                      
                        if (!empty($rx->value->originalText)) {                                                                                                                                                                                                         
                            $summary['reaction_description'] = (string)$rx->value->originalText;                                                                                                                                                                        
                        } elseif (!empty($rx->value['code'])) {                                                                                                                                                                                                         
                            $summary['reaction_description'] = (string)$rx->value['code'];                                                                                                                                                                              
                        }                                                                                                                                                                                                                                               
                    }                                                                                                                                                                                                                                                   
                    if (empty($summary['reactionstartdate']) && !empty($rx->effectiveTime->low['value'])) {                                                                                                                                                             
                        $summary['reactionstartdate'] = (string)$rx->effectiveTime->low['value'];                                                                                                                                                                       
                    }                                                                                                                                                                                                                                                   
                }                                                                                                                                                                                                                                                       
            }                                                                                                                                                                                                                                                           
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       
            $death = $xml->xpath('//observation[code/@code="34" or code/@code="death"]/value/@value');                                                                                                                                                                  
            if (!empty($death) && in_array((string)$death[0], array('1', 'true'), true)) {                                                                                                                                                                              
                $summary['seriousness']['death'] = 'Yes';                                                                                                                                                                                                               
            }                                                                                                                                                                                                                                                           
                                                                                                                                                                                                                                                                        
            $hospital = $xml->xpath('//observation[code/@code="32" or code/@code="hospitalization"]/value/@value');                                                                                                                                                     
            if (!empty($hospital) && in_array((string)$hospital[0], array('1', 'true'), true)) {                                                                                                                                                                        
                $summary['seriousness']['hospitalization'] = 'Yes';                                                                                                                                                                                                     
            }                                                                                                                                                                                                                                                           
                                                                                                                                                                                                                                                                        
            $life = $xml->xpath('//observation[code/@code="33" or code/@code="life_threatening"]/value/@value');                                                                                                                                                        
            if (!empty($life) && in_array((string)$life[0], array('1', 'true'), true)) {                                                                                                                                                                                
                $summary['seriousness']['life_threatening'] = 'Yes';                                                                                                                                                                                                    
            }                                                                                                                                                                                                                                                           
                                                                                                                                                                                                                                                                        
            $disability = $xml->xpath('//observation[code/@code="35" or code/@code="disability"]/value/@value');                                                                                                                                                        
            if (!empty($disability) && in_array((string)$disability[0], array('1', 'true'), true)) {                                                                                                                                                                    
                $summary['seriousness']['disability'] = 'Yes';                                                                                                                                                                                                          
            }                                                                                                                                                                                                                                                           
                                                                                                                                                                                                                                             
            $substances = $xml->xpath('//substanceAdministration');                                                                                                                                                                                                     
            if (!empty($substances)) {                                                                                                                                                                                                                                  
                foreach ($substances as $sub) {                                                                                                                                                                                                                         
                    $drugName = '';                                                                                                                                                                                                                                     
                    if (!empty($sub->consumable->manufacturedProduct->manufacturedLabeledDrug->name)) {                                                                                                                                                                 
                        $drugName = (string)$sub->consumable->manufacturedProduct->manufacturedLabeledDrug->name;                                                                                                                                                       
                    }                                                                                                                                                                                                                                                   
                                                                                                                                                                                                                                                                        
                    $route = !empty($sub->routeCode['code']) ? (string)$sub->routeCode['code'] : '';                                                                                                                                                                    
                    $dose = !empty($sub->doseQuantity['value']) ? (string)$sub->doseQuantity['value'] : '';                                                                                                                                                             
                    $doseUnit = !empty($sub->doseQuantity['unit']) ? (string)$sub->doseQuantity['unit'] : '';                                                                                                                                                           
                                                                                                                                                                                                                                                                        
                    if ($drugName !== '') {                                                                                                                                                                                                                             
                        $summary['drugs'][] = array(                                                                                                                                                                                                                    
                            'name' => $drugName,                                                                                                                                                                                                                        
                            'route' => $route,                                                                                                                                                                                                                          
                            'dosage' => trim($dose . ' ' . $doseUnit),                                                                                                                                                                                                  
                            'start_date' => !empty($sub->effectiveTime->low['value']) ? (string)$sub->effectiveTime->low['value'] : '',                                                                                                                                 
                            'end_date' => !empty($sub->effectiveTime->high['value']) ? (string)$sub->effectiveTime->high['value'] : '',                                                                                                                                 
                        );                                                                                                                                                                                                                                              
                    }                                                                                                                                                                                                                                                   
                }                                                                                                                                                                                                                                                       
            }                                                                                                                                                                                                                                                           
                                                                                                                                                                                                                                            
            $narratives = $xml->xpath('//observation[code/@code="narrative" or code/@code="case_summary"]/value');                                                                                                                                                      
            if (!empty($narratives)) {                                                                                                                                                                                                                                  
                $summary['narrative'] = (string)$narratives[0];                                                                                                                                                                                                         
            }                                                                                                                                                                                                                                                           
                                                                                                                                                                                                                                                                        
            return $summary;                                                                                                                                                                                                                                            
        }                                                                                                                                                                                                                                                               
    }                                               